const formatPrice = (price) => {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(price);
};

export default formatPrice;

const validateContactForm = (values) => {
  const errors = {};

  if (!values.name || values.name.trim() === "") {
    errors.name = "Name is required";
  }

  if (!values.email || values.email.trim() === "") {
    errors.email = "Email is required";
  } else {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(values.email)) {
      errors.email = "Please enter a valid email address";
    }
  }

  if (!values.message || values.message.trim() === "") {
    errors.message = "Message is required";
  }

  return errors;
};

export default validateContactForm;

import { Box, Group, Text, Burger, Drawer, Stack, Anchor } from "@mantine/core";
import { useDisclosure, useMediaQuery } from "@mantine/hooks";
import { IconMenu2, IconX } from "@tabler/icons-react";

const Navbar = () => {
  const [opened, { toggle, close }] = useDisclosure(false);
  const isMobile = useMediaQuery("(max-width: 768px)");

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
    }
    if (opened) {
      close();
    }
  };

  const navLinks = [
    { label: "Home", id: "hero" },
    { label: "Menu", id: "menu" },
    { label: "Contact", id: "contact" }
  ];

  const NavItems = () => (
    <>
      {navLinks.map((link) => (
        <Anchor
          key={link.id}
          href={`#${link.id}`}
          onClick={(e) => {
            e.preventDefault();
            scrollToSection(link.id);
          }}
          style={{
            color: "#3E2723",
            textDecoration: "none",
            fontWeight: 500,
            fontSize: "1rem",
            cursor: "pointer"
          }}
          c="coffeeBrown.7"}
        >
          {link.label}
        </Anchor>
      ))}
    </>
  );

  return (
    <Box
      component="nav"
      style={{
        position: "sticky",
        top: 0,
        backgroundColor: "#FFFDD0",
        borderBottom: "1px solid #E0D5C5",
        zIndex: 100
      }}
      p="md"
    >
      <Group justify="space-between" align="center">
        <Text
          size="xl"
          fw={700}
          c="coffeeBrown.7"
          style={{ cursor: "pointer" }}
          onClick={() => scrollToSection("hero")}
        >
          Brew & Bean Café
        </Text>

        {isMobile ? (
          <>
            <Burger opened={opened} onClick={toggle} aria-label="Toggle navigation" color="#654321" />
            <Drawer
              opened={opened}
              onClose={close}
              position="right"
              title="Menu"
              closeButtonProps={{ icon: <IconX size={24} /> }}
              styles={{
                header: { backgroundColor: "#FFFDD0" },
                body: { backgroundColor: "#FFFDD0" }
              }}
            >
              <Stack gap="lg" pt="lg">
                {navLinks.map((link) => (
                  <Text
                    key={link.id}
                    component="a"
                    href={`#${link.id}`}
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection(link.id);
                    }}
                    size="lg"
                    fw={500}
                    c="coffeeBrown.7"
                    style={{ cursor: "pointer", textDecoration: "none" }}
                  >
                    {link.label}
                  </Text>
                ))}
              </Stack>
            </Drawer>
          </>
        ) : (
          <Group gap="xl">
            <NavItems />
          </Group>
        )}
      </Group>
    </Box>
  );
};

export default Navbar;

import { Card, Text, Image, Group, Badge } from "@mantine/core";
import formatPrice from "../../lib/formatPrice";

const CoffeeCard = ({ coffee, onClick }) => {
  return (
    <Card
      shadow="sm"
      padding="lg"
      radius="lg"
      style={{
        backgroundColor: "var(--mantine-color-cream-0)",
        cursor: "pointer",
        transition: "transform 0.2s ease, box-shadow 0.2s ease"
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = "translateY(-4px)";
        e.currentTarget.style.boxShadow = "var(--mantine-shadow-md)";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = "translateY(0)";
        e.currentTarget.style.boxShadow = "var(--mantine-shadow-sm)";
      }}
      onClick={() => onClick && onClick(coffee)}
    >
      <Card.Section>
        <Image
          src={coffee.image}
          alt={coffee.name}
          height={200}
          style={{ objectFit: "cover" }}
        />
      </Card.Section>

      <Group position="apart" mt="md" mb="xs">
        <Text weight={600} size="lg" color="coffeeBrown.7">
          {coffee.name}
        </Text>
        <Badge color="coffeeBrown" variant="light" size="lg">
          {formatPrice(coffee.price)}
        </Badge>
      </Group>

      <Text size="sm" color="coffeeBrown.6" lineClamp={3}>
        {coffee.description}
      </Text>
    </Card>
  );
};

export default CoffeeCard;

import { Tabs } from "@mantine/core";

const CategoryTabs = ({ categories, activeCategory, onChange }) => {
  return (
    <Tabs
      value={activeCategory}
      onChange={onChange}
      variant="default"
      color="coffeeBrown"
      style={{ width: "100%" }}
    >
      <Tabs.List grow>
        {categories.map((category) => (
          <Tabs.Tab
            key={category.id}
            value={category.id}
            style={{
              fontWeight: 500,
              color: "var(--mantine-color-coffeeBrown-7)"
            }}
          >
            {category.label}
          </Tabs.Tab>
        ))}
      </Tabs.List>
    </Tabs>
  );
};

export default CategoryTabs;

import { Modal, Image, Text, Group, Badge } from "@mantine/core";
import formatPrice from "../../lib/formatPrice";

const Lightbox = ({ coffee, opened, onClose }) => {
  if (!coffee) return null;

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title={coffee.name}
      centered
      size="md"
      styles={{
        title: {
          color: "var(--mantine-color-coffeeBrown-7)",
          fontWeight: 600
        }
      }}
    >
      <Image
        src={coffee.image}
        alt={coffee.name}
        style={{ objectFit: "cover", width: "100%", borderRadius: "var(--mantine-radius-md)" }}
        mb="md"
      />
      <Group position="apart" mb="sm">
        <Text weight={600} color="coffeeBrown.7">
          {coffee.name}
        </Text>
        <Badge color="coffeeBrown" size="lg">
          {formatPrice(coffee.price)}
        </Badge>
      </Group>
      <Text color="coffeeBrown.6" mb="md">
        {coffee.description}
      </Text>
    </Modal>
  );
};

export default Lightbox;

import { Box, Title, Text, Button, Group, Container } from "@mantine/core";
import siteContent from "../../data/siteContent";

